import {VERSION,money,clamp,practiceFrames,run,validateRecording} from './engine.mjs';
import {createStrategyLab} from './strategy-ui.mjs';
import {validateRules} from './strategy.mjs';

const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='ds-market-lab:sessions:v1';
const signed=n=>(n>=0?'+':'−')+money(Math.abs(n));
const price=n=>(n/100).toLocaleString('en-US',{maximumFractionDigits:2})+'¢';
const quantity=n=>(n/100).toLocaleString('en-US',{maximumFractionDigits:2});
const clock=t=>new Date(t).toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false,timeZone:'America/New_York'});
const date=t=>new Date(t).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZone:'America/New_York'});
const pct=(n,d)=>d?(100*n/d).toFixed(1)+'%':'—';
const labels={mixed:'Mixed market',trend:'Trending market',whipsaw:'Choppy market'};
const pages={compare:['THE COMPARISON LAB','Two agents. One market.','The same signal. Two ways to manage a $50 bankroll.'],replay:['EVERY DECISION, IN ORDER','Rewind the round.','Move through the same timeline and compare both agents.'],history:['THE TRADE JOURNAL','Nothing gets lost.','Inspect entries, exits, amounts, fees, and decision notes.'],results:['THE EXPERIMENT','Compare the results.','Balances and costs at the selected point in this practice session.'],setup:['YOUR WORKSPACE','Connections & test rules.','The dashboard is ready to practice. Live connections come next.']};
let view=location.hash.slice(1)||'compare',playing=false,timer=null,speed=60,chartSide='YES',roundChoice='current',agentFilter='ALL',typeFilter='ALL',storageOK=true,sessionList=[],active=null,report=null;
let savedCursor=0;
pages.strategy=['RESEARCH & RULES','Strategy Lab.','Study the waves. Inspect the trades. Test the rules.'];
const lab=createStrategyLab({session:()=>active,refresh:render,notify:toast,useAll:()=>{pause();active.cursor=active.frames.length-1;save();},openTest:openStrategyTest});

function makeSession(scenario='mixed'){
 return {kind:'ds-market-lab-recording',version:VERSION,id:globalThis.crypto?.randomUUID?.()||String(Date.now()),title:labels[scenario],scenario,source:'fictional-practice',created:new Date().toISOString(),cursor:24,frames:practiceFrames(scenario)};
}
function hydrate(){
 try{const raw=JSON.parse(localStorage.getItem(key)||'null');if(raw&&Array.isArray(raw.sessions)){
  for(const s of raw.sessions){try{validateRecording(s);if(s.strategyRules)s.strategyRules=validateRules(s.strategyRules);if(typeof s.id!=='string'||typeof s.created!=='string')continue;s.title=String(s.title||'Imported session').slice(0,80);s.source=s.source==='fictional-practice'?'fictional-practice':'unverified-import';s.cursor=clamp(Number.isInteger(s.cursor)?s.cursor:0,0,s.frames.length-1);sessionList.push(s);}catch{}}
  active=sessionList.find(s=>s.id===raw.active)||sessionList.at(-1);
 }}catch{storageOK=false;}
 if(!active){active=makeSession();sessionList.push(active);}report=run(active.frames,active.strategyRules||{});save();
}
function save(){try{localStorage.setItem(key,JSON.stringify({active:active.id,sessions:sessionList}));storageOK=true;}catch{storageOK=false;}savedCursor=active.cursor;saveStatus();}
function saveStatus(){const el=$('#save-status');if(el){el.textContent=storageOK?'Saved on this browser only · Export to keep a copy':'Browser save unavailable · Export a copy';el.classList.toggle('storage-warning',!storageOK);}}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('visible');setTimeout(()=>el.classList.remove('visible'),4000);}
const frame=()=>active.frames[active.cursor];
const wallets=()=>report.snapshots[active.cursor];
const events=()=>report.events.filter(e=>e.index<=active.cursor);
function pause(){playing=false;if(timer)clearInterval(timer);timer=null;save();}
function play(){
 if(active.cursor>=active.frames.length-1){active.cursor=0;}playing=true;
 if(timer)clearInterval(timer);
 timer=setInterval(()=>{active.cursor=Math.min(active.frames.length-1,active.cursor+Math.max(1,Math.round(speed/60)));if(active.cursor>=active.frames.length-1)pause();if(active.cursor-savedCursor>=12)save();render();},speed<60?1000:250);
 render();
}
function setCursor(index){pause();active.cursor=clamp(index,0,active.frames.length-1);save();render();}
function setView(next){if(!pages[next])next='compare';if(!['compare','replay'].includes(next))pause();view=next;render();}
function shownRound(){const f=frame();return roundChoice==='current'?f.market:roundChoice;}
function roundFrames(){const market=shownRound();return active.frames.map((f,i)=>({...f,index:i})).filter(f=>f.market===market&&f.index<=active.cursor);}
function roundOptions(){const out=[];active.frames.slice(0,active.cursor+1).forEach(f=>{if(!out.includes(f.market))out.push(f.market);});return out;}
function latest(w,type){return events().filter(e=>e.wallet===w.id&&e.market===shownRound()&&(!type||e.type===type)).at(-1);}

function marketStrip(){const f=frame();return `<div class="market-strip"><div class="market-cell"><span class="label">Bitcoin · Fictional spot price</span><span class="market-value">${money(Math.round(f.btc*100))}</span></div><div class="market-cell"><span class="label">Round target</span><span class="market-value">${money(Math.round(f.target*100))}</span></div><div class="market-cell"><span class="label">Time left in round</span><span class="market-value blue">${String(Math.floor(f.secondsLeft/60)).padStart(2,'0')}:${String(f.secondsLeft%60).padStart(2,'0')}</span><span class="tiny-label">${f.end?'CLOSED':'15 MIN'}</span></div><div class="market-cell"><span class="label">YES buy / sell quotes</span><span class="market-value">${price(f.yesAsk)} <span class="muted">/</span> ${price(f.yesBid)}</span></div></div>`;}
function sessionToolbar(){return `<div class="session-toolbar"><div class="session-info"><span class="pill ${playing?'running':''}">${playing?'PLAYING':active.cursor===active.frames.length-1?'COMPLETE':'PAUSED'}</span><b>${esc(active.title)}</b><span>·</span><span>${active.source==='fictional-practice'?'Fictional':'Unverified import'}</span></div><div class="actions"><button class="button small secondary" data-action="toggle-play">${playing?'Ⅱ Pause':'▷ Play'}</button><button class="button small ghost" data-action="finish" title="Advance to the end of all six practice rounds">Run to end</button></div></div>`;}

function chart(id){
 const points=roundFrames(),f=points.at(-1);if(!f)return '<p class="empty-state">Select a round already reached in this session.</p>';
 const mobile=window.innerWidth<=600,W=mobile?245:530,H=244,L=mobile?36:42,R=mobile?27:39,T=25,B=29,width=W-L-R,height=H-T-B;
 const value=f=>chartSide==='YES'?(f.yesBid+f.yesAsk)/2:10000-(f.yesBid+f.yesAsk)/2;
 const vals=points.map(value),min=Math.max(0,Math.floor((Math.min(...vals)-1400)/1000)*1000),max=Math.min(10000,Math.ceil((Math.max(...vals)+1400)/1000)*1000),range=Math.max(1000,max-min);
 const x=f=>L+(900-f.secondsLeft)/900*width,y=p=>T+(max-p)/range*height;
 const path=points.map((f,i)=>`${i?'L':'M'}${x(f).toFixed(2)} ${y(value(f)).toFixed(2)}`).join(' ');
 const area=path+` L${x(f)} ${H-B} L${x(points[0])} ${H-B} Z`;
 const markers=events().filter(e=>e.wallet===id&&e.market===f.market&&e.type!=='SETTLE').map(e=>{
  const ef=active.frames[e.index],p=e.side===chartSide?e.price:10000-e.price,c=e.type==='BUY'?'#42d8a0':'#f6bd64';
  return `<g data-event="${e.id}" tabindex="0" role="button" aria-label="${e.type} ${e.side} at ${price(e.price)} at ${clock(e.time)}"><title>${e.type} ${e.side} ${price(e.price)} · ${clock(e.time)}</title><circle class="chart-point" cx="${x(ef)}" cy="${y(p)}" r="5" fill="${c}"/><text class="marker-label" x="${clamp(x(ef),L+25,W-R-25)}" y="${clamp(y(p)+(e.type==='BUY'?22:-13),T+10,H-B-5)}" text-anchor="middle">${e.type==='BUY'?'B':'S'} ${price(e.price)}</text></g>`;
 }).join('');
 const ticks=[0,.25,.5,.75,1].map(t=>`<line class="gridline" x1="${L}" y1="${T+t*height}" x2="${W-R}" y2="${T+t*height}"/><text x="${L-8}" y="${T+t*height+4}" text-anchor="end">${price(max-t*range)}</text>`).join('');
 const times=(mobile?[0,900]:[0,300,600,900]).map(s=>`<line class="gridline" x1="${L+s/900*width}" y1="${T}" x2="${L+s/900*width}" y2="${H-B}" opacity=".45"/><text x="${L+s/900*width}" y="${H-9}" text-anchor="middle">${String(Math.floor(s/60)).padStart(2,'0')}:00</text>`).join('');
 return `<svg class="price-chart" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" role="img" aria-label="${chartSide} contract midpoint chart with Agent ${id} trade markers; cents by elapsed minutes"><defs><linearGradient id="area-${id}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#2585c9" stop-opacity=".19"/><stop offset="1" stop-color="#2585c9" stop-opacity="0"/></linearGradient></defs>${ticks}${times}<path d="${area}" fill="url(#area-${id})"/><path d="${path}" class="chart-line"/><line class="cursor" x1="${x(f)}" x2="${x(f)}" y1="${T}" y2="${H-B}"/>${markers}<circle cx="${x(f)}" cy="${y(value(f))}" r="3.5" fill="#a9dcff"/><text x="${W-R+5}" y="${clamp(y(value(f))+4,T+5,H-B)}" style="fill:#74c5ff;font-weight:600">${price(value(f))}</text></svg>`;
}
function tradeRow(e){if(!e)return '';return `<div class="trade-row"><span class="event-type ${e.type.toLowerCase()}">${e.type==='SETTLE'?'END':e.type}</span><span><span class="trade-time">${clock(e.time)}</span><b>${e.side} ${price(e.price)}</b></span><span class="trade-money">${e.type==='BUY'?'−':'+'}${money(Math.abs(e.net))}</span></div>`;}
function agentCard(w){
 const gain=w.equity-w.start,buy=latest(w,'BUY'),exit=events().filter(e=>e.wallet===w.id&&e.market===shownRound()&&e.type!=='BUY').at(-1),last=exit||buy;
 let reason=last?.reason||'Waiting for the practice entry signal. Skipping a trade is allowed.';
 if(w.position)reason=`Holding ${w.position.side}. Exit if its sell quote rises ${(active.strategyRules?.takeProfit??1200)/100}¢ above entry, falls ${(active.strategyRules?.stopLoss??1000)/100}¢ below entry, or the round is nearly over.`;
 const position=w.position?`${quantity(w.position.quantity)} ${w.position.side} @ ${price(w.position.price)}`:'No open position';
 return `<article class="agent-card agent-${w.id.toLowerCase()}"><div class="agent-head"><div class="agent-title"><h2><span class="agent-letter">${w.id}</span>Agent ${w.id}</h2><span class="strategy-tag">${w.id==='A'?'$10 max / trade':'Flexible size'}</span></div><div class="balance-line"><strong class="balance">${money(w.equity)}</strong><span class="gain ${gain<0?'negative':''}">${signed(gain)}</span></div><div class="wallet-facts"><div><span class="label">Available cash</span><strong>${money(w.cash)}</strong></div><div><span class="label">Started with</span><strong>$50.00</strong></div><div><span class="label">Realized net</span><strong class="${w.realized<0?'red':'green'}">${signed(w.realized)}</strong></div></div></div><div class="chart-area"><div class="chart-head"><strong>${chartSide} contract · midpoint</strong><div class="chart-legend"><span>Buy</span><span>Sell</span></div></div>${chart(w.id)}<div class="chart-caption">Elapsed minutes · Same feed, same clock</div></div><div class="trade-summary">${buy?tradeRow(buy)+tradeRow(exit):'<div class="empty-trade">No entry in this round yet.</div>'}<div class="position-line"><span class="status-indicator"></span><b>${position}</b>${exit?`<br>Latest exit net <span class="${exit.pnl<0?'red':'green'}">${signed(exit.pnl)}</span>`:''}</div></div><div class="decision-box"><div class="decision-header"><strong>${w.position?'CURRENT EXIT PLAN':last?'WHY '+(last.type==='BUY'?'IT BOUGHT':last.type==='SELL'?'IT SOLD':'IT SETTLED'):'WATCHING THE ROUND'}</strong>${last?`<button class="text-button" data-event="${last.id}">Inspect decision ↗</button>`:''}</div><p>${esc(reason)}</p></div></article>`;
}
function timeline(){const rounds=new Set(active.frames.map(f=>f.market)).size;return `<section class="timeline-panel" aria-label="Session playback"><div class="timeline-top"><h2>${view==='replay'?'Session replay':'Decision timeline'}</h2><span>${active.cursor+1} / ${active.frames.length} frames · ${clock(frame().time)} ET</span></div><div class="timeline-controls"><button class="step-button" data-action="previous" aria-label="Previous decision">‹</button><button class="play-button" data-action="toggle-play" aria-label="${playing?'Pause':'Play'} replay">${playing?'Ⅱ':'▷'}</button><button class="step-button" data-action="next" aria-label="Next decision">›</button><input class="scrubber" id="timeline" type="range" min="0" max="${active.frames.length-1}" value="${active.cursor}" aria-label="Replay position"><span class="timecode">${clock(frame().time)}</span><select class="select" id="speed" aria-label="Playback speed">${[15,60,300].map(n=>`<option value="${n}" ${n===speed?'selected':''}>${n}×</option>`).join('')}</select></div><div class="timeline-foot"><span>${clock(active.frames[0].time)} ET</span><span>${rounds} ${active.source==='fictional-practice'?'fictional':'recorded'} round${rounds===1?'':'s'} · No future trades shown</span><span>${clock(active.frames.at(-1).time)} ET</span></div></section>`;}
function comparison(){return marketStrip()+sessionToolbar()+`<div class="filter-row"><label>Chart <select class="select" id="chart-side"><option ${chartSide==='YES'?'selected':''}>YES</option><option ${chartSide==='NO'?'selected':''}>NO</option></select></label><label>Round <select class="select" id="round"><option value="current">Follow current round</option>${roundOptions().map((m,i)=>`<option value="${esc(m)}" ${roundChoice===m?'selected':''}>Round ${i+1}</option>`).join('')}</select></label></div><section class="agent-grid" aria-label="Agent comparison">${wallets().map(agentCard).join('')}</section>`+timeline()+`<p class="section-note">Balances include estimated open-position value after modeled exit fees. A displayed value is not a guaranteed fill. Markers show each trade’s actual simulated price; opposite-side trades use the complementary chart position.</p>`;}
function history(){
 const list=events().filter(e=>(agentFilter==='ALL'||e.wallet===agentFilter)&&(typeFilter==='ALL'||e.type===typeFilter)).toReversed();
 return `<section class="panel"><div class="panel-title"><div><h2>Trade history</h2><p>${esc(active.title)} · Up to ${clock(frame().time)} ET</p></div><div class="actions"><button class="button small secondary" data-action="export-json">Export session</button><button class="button small ghost" data-action="export-csv">CSV</button></div></div><div class="filter-row"><label>Agent <select id="agent-filter" class="select">${['ALL','A','B'].map(n=>`<option value="${n}" ${agentFilter===n?'selected':''}>${n==='ALL'?'Both agents':'Agent '+n}</option>`).join('')}</select></label><label>Action <select id="type-filter" class="select">${['ALL','BUY','SELL','SETTLE'].map(n=>`<option ${typeFilter===n?'selected':''}>${n}</option>`).join('')}</select></label></div><div class="table-wrap"><table><thead><tr><th>Time ET</th><th>Agent</th><th>Action</th><th>Side / price</th><th>Contracts</th><th>Cash change</th><th>Fee</th><th>Net profit</th><th></th></tr></thead><tbody>${list.map(e=>`<tr data-event="${e.id}" tabindex="0" aria-label="Inspect Agent ${e.wallet} ${e.type} at ${clock(e.time)}"><td>${clock(e.time)}</td><td class="${e.wallet==='A'?'blue':''}">${e.wallet}</td><td><span class="event-type ${e.type.toLowerCase()}">${e.type}</span></td><td>${e.side} ${price(e.price)}</td><td>${quantity(e.quantity)}</td><td>${signed(e.net)}</td><td>${money(e.fee)}</td><td class="${e.pnl<0?'red':'green'}">${e.pnl===undefined?'—':signed(e.pnl)}</td><td class="blue">Inspect ↗</td></tr>`).join('')}</tbody></table>${list.length?'':'<div class="empty-state">No trades at this point. Play the practice session or move the replay slider.</div>'}</div><p class="section-note">Select any row to see its recorded inputs and reason. Exported CSV includes only decisions already reached.</p></section>`+sessionHistory();
}
function equityChart(){const points=report.snapshots.slice(0,active.cursor+1),values=points.flatMap(p=>p.map(w=>w.equity)),lo=Math.min(4500,...values)-200,hi=Math.max(5500,...values)+200,W=900,H=230,L=50,R=20,T=15,B=30;let out='';for(let i=0;i<=4;i++){const v=lo+(hi-lo)*i/4,y=H-B-i/4*(H-T-B);out+=`<line x1="${L}" x2="${W-R}" y1="${y}" y2="${y}" stroke="#26374d"/><text x="${L-9}" y="${y+4}" text-anchor="end" fill="#8c9fb7" font-size="11">${money(v)}</text>`;}
 for(let w=0;w<2;w++){const path=points.map((p,i)=>`${i?'L':'M'}${L+i/(active.frames.length-1)*(W-L-R)} ${H-B-(p[w].equity-lo)/(hi-lo)*(H-T-B)}`).join(' ');out+=`<path d="${path}" fill="none" stroke="${w?'#bc9cff':'#4bb5ff'}" stroke-width="2.5"/>`;}
 return `<svg class="equity-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Estimated equity comparison: Agent A blue, Agent B purple, both start at $50">${out}<text x="${L}" y="${H-5}" fill="#8c9fb7" font-size="10">Session start</text><text x="${W-R}" y="${H-5}" text-anchor="end" fill="#8c9fb7" font-size="10">Session end</text></svg>`;
}
function results(){const ws=wallets();return `<div class="result-wallets">${ws.map(w=>`<section class="panel"><div class="panel-title"><h2>Agent ${w.id}</h2><span class="pill">${w.id==='A'?'$10 CAP':'FLEXIBLE'}</span></div><strong class="balance">${money(w.equity)}</strong> <span class="gain ${w.equity<5000?'negative':''}">${signed(w.equity-5000)}</span><dl><dt>Available cash</dt><dd>${money(w.cash)}</dd><dt>Realized net</dt><dd class="${w.realized<0?'red':'green'}">${signed(w.realized)}</dd><dt>Modeled fees paid</dt><dd>${money(w.fees)}</dd><dt>Closed trades</dt><dd>${w.trades}</dd><dt>Wins / losses / flat</dt><dd>${w.wins} / ${w.losses} / ${w.trades-w.wins-w.losses}</dd><dt>Win rate</dt><dd>${pct(w.wins,w.trades)}</dd><dt>Max drawdown</dt><dd>${money(w.maxDrawdown)}</dd><dt>Open position</dt><dd>${w.position?w.position.side:'None'}</dd></dl></section>`).join('')}</div><section class="panel"><div class="panel-title"><div><h2>Bankroll over time</h2><p>Estimated equity after modeled costs · Reached frames only</p></div><div class="pillrow"><span class="blue">● A</span><span style="color:var(--purple)">● B</span></div></div>${equityChart()}<p class="section-note">Fictional results verify the interface and accounting. They do not measure real-world predictive performance.</p></section>`+sessionHistory();}
function sessionHistory(){return `<section class="panel"><div class="panel-title"><div><h2>Saved test sessions</h2><p>New tests preserve earlier sessions. Stored on this browser.</p></div><button class="button small ghost" data-action="import">Import</button></div><div class="session-list">${sessionList.toReversed().map(s=>`<div class="session-entry"><div><strong>${esc(s.title)}</strong> ${s.id===active.id?'<span class="pill">OPEN</span>':''}<small>Created ${date(s.created)} ET · ${s.source==='fictional-practice'?'Fictional practice':'Unverified import'} · ${s.cursor+1} / ${s.frames.length} frames</small></div><button class="button small secondary" data-session="${esc(s.id)}">${s.id===active.id?'Replay':'Open'}</button></div>`).join('')}</div></section>`;}
function setup(){return `<div class="setup-grid"><div><section class="panel"><h2>Connection status</h2><p class="section-note">This version runs locally in your browser. No connection below has been activated.</p>${[['Practice simulator','Working here · No credentials needed','Ready','ready'],['Kalshi market data','Quotes, order book, and verified settlements','Not connected',''],['AI research','Recorded evidence and structured strategy decisions','Not connected',''],['Mac background runner','Runs independently of the phone dashboard','Set up at home',''],['Cloud synchronization','Shared history through Supabase','Not connected','']].map(([title,desc,status,ready])=>`<div class="setup-row"><div><strong>${title}</strong><small>${desc}</small></div><span class="status-tag ${ready}">${status}</span></div>`).join('')}</section><section class="panel"><h2>Tonight on the Mac</h2><div class="explain-list"><p><strong>1 · Set up the runner</strong>Prepare the background process and confirm that the Mac stays awake while a test is running.</p><p><strong>2 · Connect data and AI safely</strong>Configure credentials outside the dashboard. Verify market rules, fees, timing, and available liquidity before collecting a real paper session.</p><p><strong>3 · Connect shared storage</strong>Confirm the exact Supabase project and add isolated paper-trading records with sign-in and access controls.</p><p><strong>4 · Start the month-long experiment</strong>Use real incoming quotes and realistic simulated fills, log every decision, and review the results together.</p></div></section></div><div><section class="panel"><h2>The two bankrolls</h2><div class="rule-columns"><div><h3>Agent A</h3><p>Starts with $50.<br>Maximum $10 per position, including entry costs.<br>May use smaller amounts.</p></div><div><h3>Agent B</h3><p>Starts with $50.<br>No fixed bet-size cap.<br>May use any amount up to available cash.</p></div></div><p class="section-note">Both reuse returned principal and winnings. No borrowing, no automatic daily refill. A new test starts fresh wallets and preserves the old session.</p><div class="setup-cta"><button class="button" data-action="new">＋ New test session</button><button class="button secondary" data-action="export-json">Export session</button></div></section><section class="panel"><h2>What this practice strategy does</h2><div class="explain-list"><p><strong>Shared entry signal</strong>Two minutes into each fictional round, follow the previous 60 seconds of spot-price movement: YES for up, NO for down.</p><p><strong>Different sizing</strong>A uses up to $10. B varies its cash allocation with the strength of that same sample signal; the choppy example uses 90%.</p><p><strong>Shared exit rule</strong>Attempt to sell at +12¢ or −10¢ from entry, or with 30 seconds remaining. No fill is guaranteed when quotes are stale or liquidity is missing.</p></div><div class="strategy-code">Model: example-v${VERSION}<br>Fee assumption: ceil(0.07 × contracts × price × (1 − price)), in cents.<br>Fractional quantities are a practice assumption, not verified market support.<br>Quotes sampled every 15 seconds; no network latency modeled.</div><p class="section-note">This is a transparent interface exercise, not an AI model, trading recommendation, or historical backtest. Live tests must use the actual market’s current rules and costs.</p></section><section class="panel"><h2>Deployment & identity</h2><p class="section-note">Prepared as a portable web app for Netlify. This preview has no API secrets, accounts, cloud sync, or order-submission code. Product icon artwork is still awaiting your design approval; Home Screen installation comes afterward.</p></section></div></div>`;}

function render(){
 if(!pages[view])view='compare';const [eyebrow,title,subtitle]=pages[view];
 $('#eyebrow').textContent=eyebrow;$('#page-title').textContent=title;$('#page-subtitle').textContent=subtitle;$('#breadcrumb').textContent=view.toUpperCase();
 document.querySelectorAll('[data-view]').forEach(a=>{a.classList.toggle('active',a.dataset.view===view);if(a.dataset.view===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 $('#view').innerHTML=view==='strategy'?lab.render():view==='history'?history():view==='results'?results():view==='setup'?setup():comparison();saveStatus();
}
function openModal(content){pause();$('#modal-content').innerHTML=content;if(!$('#modal').open)$('#modal').showModal();render();}
function inspect(id){const e=events().find(e=>e.id===id);if(!e)return;const f=active.frames[e.index];
 openModal(`<div class="eyebrow">RECORDED PRACTICE DECISION</div><h2>Why it ${e.type==='BUY'?'bought':e.type==='SELL'?'sold':'settled'}.</h2><p class="modal-subtitle">Agent ${e.wallet} · ${clock(e.time)} ET · ${esc(e.market)}</p><div class="detail-grid"><div class="detail-item"><span class="label">Action / contract</span><strong class="${e.type==='BUY'?'green':'amber'}">${e.type} ${e.side}</strong></div><div class="detail-item"><span class="label">Simulated fill price</span><strong>${price(e.price)}</strong></div><div class="detail-item"><span class="label">${e.type==='BUY'?'Total spent, incl. fee':'Net received, after fee'}</span><strong>${money(Math.abs(e.net))}</strong></div><div class="detail-item"><span class="label">Contracts</span><strong>${quantity(e.quantity)}</strong></div></div><div class="reason-panel"><h3>Recorded reason</h3><p>${esc(e.reason)}</p></div><div class="detail-grid"><div class="detail-item"><span class="label">Spot / target at decision</span><strong style="font-size:12px">${money(Math.round(f.btc*100))} / ${money(Math.round(f.target*100))}</strong></div><div class="detail-item"><span class="label">YES ask / bid at decision</span><strong style="font-size:12px">${price(f.yesAsk)} / ${price(f.yesBid)}</strong></div><div class="detail-item"><span class="label">Modeled fee</span><strong style="font-size:12px">${money(e.fee)}</strong></div><div class="detail-item"><span class="label">Cash after decision</span><strong style="font-size:12px">${money(e.cash)}</strong></div></div><p class="detail-foot">${e.pnl!==undefined?'Net realized on this fill: '+signed(e.pnl)+'. ':''}Fictional practice · Rule version ${VERSION}. The explanation was recorded with the event; it is not a verified forecast.</p><button class="button" data-replay="${e.index}">↶ Replay at this decision</button>`);
}
function newSessionDialog(){openModal(`<div class="eyebrow">START A SEPARATE TEST</div><h2>A fresh $50 each.</h2><p class="modal-subtitle">Your current session stays saved. Nothing is topped up automatically.</p><label for="scenario">Choose fictional price behavior<select id="scenario" class="select"><option value="mixed">Mixed market · Gains and pullbacks</option><option value="trend">Trending market · Directional moves</option><option value="whipsaw">Choppy market · Frequent reversals</option></select></label><p class="detail-foot">Every scenario is deterministic. Repeating one produces the same prices and decisions. These examples test the app, not a strategy’s skill.</p><button class="button" id="create-session">Start new practice test</button>`);}
function startSession(scenario){pause();active=makeSession(scenario);active.cursor=0;sessionList.push(active);report=run(active.frames);roundChoice='current';save();$('#modal').close();location.hash='compare';view='compare';render();toast('New test started. Previous sessions are preserved.');}
function openStrategyTest(test){pause();active={kind:'ds-market-lab-recording',version:VERSION,id:crypto.randomUUID(),created:new Date().toISOString(),title:test.title,source:test.source,scenario:'strategy-test',strategyRules:validateRules(test.rules),cursor:test.eventIndex,frames:test.frames};sessionList.push(active);report=run(active.frames,active.strategyRules);roundChoice='current';save();location.hash='replay';setView('replay');toast('Opened a separate strategy replay. Original sessions are preserved.');}
function exportData(format){pause();const basename=`DS-Market-Lab-${active.id.slice(0,8)}-${active.cursor+1}`;let data,type,ext;
 if(format==='json'){data=JSON.stringify({...active,frames:active.frames.slice(0,active.cursor+1),cursor:active.cursor,exported:new Date().toISOString(),strategy:'example-v'+VERSION,notice:'Fictional or unverified recording. Not AI research or evidence of profitability.'},null,2);type='application/json';ext='json';}
 else{const columns=['time','wallet','market','type','side','price_cents','contracts','cash_change_dollars','fee_dollars','net_profit_dollars','reason'];const rows=events().map(e=>[e.time,e.wallet,e.market,e.type,e.side,e.price/100,e.quantity/100,e.net/100,e.fee/100,e.pnl===undefined?'':e.pnl/100,e.reason]);const cell=x=>{let v=String(x??'');if(/^[=+@\t\r]/.test(v))v="'"+v;return '"'+v.replaceAll('"','""')+'"';};data=[columns,...rows].map(r=>r.map(cell).join(',')).join('\r\n');type='text/csv';ext='csv';}
 const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=basename+'.'+ext;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Export created for the frames reached so far.');render();
}
function nextEvent(direction){const ix=events().filter(e=>direction<0?e.index<active.cursor:e.index>active.cursor).map(e=>e.index);if(direction>0){const future=report.events.filter(e=>e.index>active.cursor);setCursor(future[0]?.index??active.frames.length-1);}else setCursor(ix.at(-1)??0);}
function act(action){if(action==='toggle-play'){playing?pause():play();render();}else if(action==='finish')setCursor(active.frames.length-1);else if(action==='previous')nextEvent(-1);else if(action==='next')nextEvent(1);else if(action==='new')newSessionDialog();else if(action==='import')$('#import-file').click();else if(action==='export-json')exportData('json');else if(action==='export-csv')exportData('csv');}

document.addEventListener('click',e=>{
 const target=e.target.closest('[data-action],[data-event],[data-session],[data-replay]');if(!target)return;
 if(target.dataset.action)act(target.dataset.action);
 else if(target.dataset.event)inspect(target.dataset.event);
 else if(target.dataset.session){pause();active=sessionList.find(s=>s.id===target.dataset.session)||active;report=run(active.frames,active.strategyRules||{});roundChoice='current';save();location.hash='replay';setView('replay');}
 else if(target.dataset.replay){$('#modal').close();roundChoice='current';setCursor(Number(target.dataset.replay));location.hash='replay';setView('replay');}
});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-event]')){e.preventDefault();inspect(e.target.dataset.event);}});
document.addEventListener('click',e=>{if(view==='strategy')lab.click(e);});
document.addEventListener('change',e=>{if(view==='strategy')lab.change(e);});
document.addEventListener('submit',e=>{if(e.target.id==='strategy-form')e.preventDefault();});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-lab-event]')){e.preventDefault();lab.click(e);}});
document.addEventListener('input',e=>{if(e.target.id==='timeline'){pause();active.cursor=clamp(Number(e.target.value),0,active.frames.length-1);e.target.setAttribute('aria-valuetext',clock(frame().time));$('.timecode').textContent=clock(frame().time);}});
document.addEventListener('change',e=>{if(e.target.id==='timeline'){save();render();$('#timeline')?.focus({preventScroll:true});}else if(e.target.id==='speed'){speed=Number(e.target.value);if(playing)play();}else if(e.target.id==='chart-side'){chartSide=e.target.value;render();}else if(e.target.id==='round'){roundChoice=e.target.value;render();}else if(e.target.id==='agent-filter'){agentFilter=e.target.value;render();}else if(e.target.id==='type-filter'){typeFilter=e.target.value;render();}});
document.addEventListener('click',e=>{if(e.target.id==='create-session')startSession($('#scenario').value);});
$('#new-session').addEventListener('click',newSessionDialog);
$('#close-modal').addEventListener('click',()=>$('#modal').close());
$('#help').addEventListener('click',()=>openModal(`<div class="eyebrow">PAPER TRADING ONLY</div><h2>Your comparison lab.</h2><div class="explain-list"><p><strong>Start with the two charts</strong>They show the same contract and time. Green markers are buys; amber markers are sells. Tap a marker or “Inspect decision” for the price, amount, and recorded reason.</p><p><strong>Try a full practice session</strong>Press Play or Run to end. Use Replay to move through each decision. Switch to Results to compare balances after modeled fees.</p><p><strong>Money rules</strong>Each wallet starts at $50. A spends at most $10 per position; B can use its available cash. Both can reuse winnings. No automatic refill.</p><p><strong>What is actually connected?</strong>Nothing external yet. Prices are fictional, decisions use a simple rule, and records stay on this browser. No API credits or real money are used. Export a session to keep a copy.</p><p><strong>Next step</strong>Connect real market data, server-side AI, and Supabase after the Mac setup. Product icon artwork remains to be approved.</p></div>`));
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>8*1024*1024)throw new Error('Choose a JSON recording smaller than 8 MB.');const raw=JSON.parse(await file.text());validateRecording(raw);const s={kind:raw.kind,version:raw.version,id:crypto.randomUUID(),created:new Date().toISOString(),title:String(raw.title||'Imported session').slice(0,80),source:'unverified-import',scenario:'import',cursor:0,frames:raw.frames,strategyRules:raw.strategyRules?validateRules(raw.strategyRules):undefined};pause();sessionList.push(s);active=s;report=run(s.frames,s.strategyRules||{});roundChoice='current';save();location.hash='replay';setView('replay');toast('Imported as unverified data. No live connection was created.');}catch(err){toast(err.message||'Could not import this recording.');}e.target.value='';});
window.addEventListener('hashchange',()=>setView(location.hash.slice(1)));
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(render,150);});
window.addEventListener('pagehide',()=>{playing=false;save();});
document.addEventListener('visibilitychange',()=>{if(document.hidden){pause();render();}});
hydrate();render();
